# owner: platform
"""Finding the stretches of opening hours nobody covers."""

from typing import Iterable, Iterator, List

from hourglass.merging import merge_spans
from hourglass.models import Span
from hourglass.parsing import format_span

def _check_inside(spans: List[Span], hours: Span) -> None:
    for span in spans:
        if span.start < hours.start or span.end > hours.end:
            text = format_span(span)
            raise ValueError(f"{text} is outside opening")

def _gaps(merged: List[Span], hours: Span) -> Iterator:
    cursor = hours.start
    for span in merged:
        if span.start > cursor:
            yield Span(cursor, span.start)
        cursor = span.end
    if cursor < hours.end:
        yield Span(cursor, hours.end)

def _label(gap: Span) -> str:
    return f"gap {format_span(gap)} ({gap.minutes} min)"

# ---
def gap_labels(
    worked: Iterable[Span], hours: Span
) -> List[str]:
    """One label per uncovered stretch of opening hours."""
    merged = merge_spans(worked)
    _check_inside(merged, hours)
    return [_label(gap) for gap in _gaps(merged, hours)]
